  const t = KV_TAX.m[x.code];
  if (!t) { x.mats = x.mats || []; x.cols = x.cols || []; return; }
  x.grps = [KV_TAX.cats[t[0]]]; x.sub = KV_TAX.subs[t[1]]; if (KV_TAX.n && KV_TAX.n[x.code]) x.name = KV_TAX.n[x.code];
